  for key,value in {'pc_port_angle':'36.2 deg','pc_port_inner_radius':'30.1 mm','pc_port_depth':'21 mm','pc_port_width':'18 mm','pc_port_start_y':'-44.2 mm','pc_port_axial_width':'40 mm','pc_cable_center_radius':'46.6 mm','pc_cable_radius':'5 mm','pc_cable_y':'-35.6 mm','pc_cable_length':'27 mm'}.items():g.parameter(key,value,'deg'if key.endswith('angle')else'mm')
  coordinates=[]
