   coordinates.append([(f'pr_pitch_x_offset+{sign}*(({r})*sin(pc_port_angle)+({t})*cos(pc_port_angle))',f'{sign}*(({r})*cos(pc_port_angle)-({t})*sin(pc_port_angle))')for r,t in [('pc_port_inner_radius','-pc_port_width/2'),('pc_port_inner_radius+pc_port_depth','-pc_port_width/2'),('pc_port_inner_radius+pc_port_depth','pc_port_width/2'),('pc_port_inner_radius','pc_port_width/2')]])
