  body=self.extrude_all(self.lugs('pc_lug_start_y','pc_lug_radius','Three closure support bosses'),'pc_split_y-pc_lug_start_y','Integral closure support bosses',fusion.FeatureOperations.JoinFeatureOperation,body)
  body=self.extrude_all(self.lugs('pc_split_y','pc_pilot_radius','Three locating pilots'),'pc_pilot_length','Three integral locating pilots',fusion.FeatureOperations.JoinFeatureOperation,body)
  body=self.extrude_all(self.lugs('-13 mm','pc_closure_screw_radius','Three closure screw passages'),'11 mm','Three closure screw passages',fusion.FeatureOperations.CutFeatureOperation,body)
  coords=[]
  for a in [90,215,325]:
   coords.append([(f'pr_pitch_x_offset+({u})*cos({a} deg)-({v})*sin({a} deg)',f'({u})*sin({a} deg)+({v})*cos({a} deg)')for u,v in [('37 mm','-11 mm'),('87 mm','-11 mm'),('87 mm','11 mm'),('37 mm','11 mm')]])
