  journal=self.revolve([('pr_bearing_rear_x','pr_axial_passage_radius'),('pr_bearing_rear_x','pr_journal_radius'),('pr_bearing_end_x','pr_journal_radius'),('pr_bearing_end_x','pr_inner_land_radius'),('pr_bearing_end_x+pc_journal_shoulder_depth','pr_inner_land_radius'),('pr_bearing_end_x+pc_journal_shoulder_depth','pc_journal_flange_radius'),('pr_bearing_end_x+pc_journal_shoulder_depth+pc_journal_flange_depth','pc_journal_flange_radius'),('pr_bearing_end_x+pc_journal_shoulder_depth+pc_journal_flange_depth','pr_axial_passage_radius')],c.xConstructionAxis,'Paired-bearing hollow journal and race shoulder')
  g.parameter('pc_web_end_x','-40.8 mm+pr_pitch_x_offset');g.parameter('pc_web_start_x','pr_bearing_end_x+1 mm');web=g.box('pc_web_end_x-pc_web_start_x','pc_split_y+25 mm','40 mm','(pc_web_start_x+pc_web_end_x)/2','(pc_split_y-25 mm)/2','0 mm','Broad perpendicular journal web');web=g.round_edges(web,'pc_web_fillet','Web edge radii');clip=g.extrude(self.x_circle('-51 mm','0 mm','0 mm','30 mm','Web radial clearance'),'pc_web_end_x+51 mm','Web radial clearance').bodies.item(0);web=g.combine(web,[clip],fusion.FeatureOperations.IntersectFeatureOperation,'Keep web within retainer clearance');body=g.combine(body,[journal,web],fusion.FeatureOperations.JoinFeatureOperation,'Integral cup and paired-bearing journal')
  for start,depth,radius,name in [('pr_motor_face_x-.5 mm','pr_bearing_end_x-pr_motor_face_x+5 mm','pr_motor_output_bolt_radius','Output screw passages'),('pr_bearing_end_x-pc_output_recess','130 mm','pc_output_head_radius','Recessed output screw head access')]:
   sk=self.x_circle(start,'pr_motor_output_pcd_radius','0 mm',radius,name+' seed');body=self.extrude_all(sk,depth,name+' seed',fusion.FeatureOperations.CutFeatureOperation,body);body=self.pattern(c.features.extrudeFeatures.item(c.features.extrudeFeatures.count-1),c.xConstructionAxis,'6','Six '+name.lower())
  start='pr_bearing_end_x-pc_output_recess-pc_output_seat_depth';end='pr_bearing_end_x-pc_output_recess';cy='pr_motor_output_pcd_radius';sk=self.polygon(c.xYConstructionPlane,[(start,cy),(start,cy+'+pr_motor_output_bolt_radius'),(end,cy+'+pc_output_seat_radius'),(end,cy)],'Standard flat-head output seat section');axsk=c.sketches.add(c.xYConstructionPlane);axsk.name='Output seat axis datum';p=g.skeleton_point(axsk,'0 mm',cy);q=g.skeleton_point(axsk,'1 mm',cy);g.point_dimensions(axsk,p,'0 mm',cy);g.point_dimensions(axsk,q,'1 mm',None);axsk.geometricConstraints.addHorizontalPoints(p,q);axis=axsk.sketchCurves.sketchLines.addByTwoPoints(p,q);axis.isConstruction=True;axsk.isVisible=False;inp=c.features.revolveFeatures.createInput(sk.profiles.item(0),axis,fusion.FeatureOperations.CutFeatureOperation);inp.participantBodies=[body];inp.setAngleExtent(False,g.value('360 deg'));f=c.features.revolveFeatures.add(inp);f.name='Standard flat-head output seat';sk.isVisible=False;body=self.pattern(f,c.xConstructionAxis,'6','Six recessed output screw seats')
  tool=g.box('pc_tool_window_width','pc_tool_window_depth','pc_tool_window_height','50 mm+pr_pitch_x_offset','-8 mm','0 mm','Roll screw front approach');tool=g.round_edges(tool,'pc_tool_window_radius','Front approach corner radii');return g.combine(body,[tool],fusion.FeatureOperations.CutFeatureOperation,'Open roll screw tool approach')
